// Channels to watch for :ticket: reactions on Lokalise push posts (same 7 as the live watcher).
// Names: aichat, pdf, realchecker, personality, brainiq, resumewise, unicopy -lokalise-github-automation.
// Not watched: #myimage-lokalise-github-automation (C0996G0TZ9D) - add it here if wanted.
const CH = ['C0BCC7KL49M', 'C096NKTSG7K', 'C0BFQ8FH9BM', 'C0ATJEBG8NB', 'C0C1Z9VRNDP', 'C09CUE3ND7V', 'C09A5TC1UCA'];
const oldest = Math.floor(Date.now() / 1000) - 3 * 86400;
return CH.map(function (c) { return { json: { channel: c, oldest: oldest } }; });

// One History item per page per channel; pairedItem points back to the Channels item.
const st = $getWorkflowStaticData('global');
st.done = st.done || {};
const chans = $('Channels').all();
const res = $input.all();
const TICKET = /^(ticket|tickets|admission_tickets)(::skin-tone-\d)?$/;
function allText(m) {
  const parts = [m.text || ''];
  for (const a of (m.attachments || [])) { parts.push(a.pretext || '', a.title || '', a.text || '', a.fallback || ''); }
  (function walk(x) { if (!x) { return; } if (Array.isArray(x)) { x.forEach(walk); return; } if (typeof x === 'object') { if (typeof x.text === 'string') { parts.push(x.text); } else if (x.text) { walk(x.text); } if (x.url) { parts.push(x.url); } walk(x.elements); walk(x.fields); } })(m.blocks || []);
  return parts.join('\n');
}
const out = []; const errors = []; const okCh = {}; let scanned = 0; const lastCur = {};
const seen = {};
for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem; const idx = Array.isArray(pi) ? pi[0].item : (pi && pi.item !== undefined ? pi.item : i);
  const ch = (chans[idx] || chans[i] || { json: {} }).json.channel;
  const b = res[i].json || {};
  if (!b.ok) { errors.push(ch + ': ' + (b.error || 'request failed')); continue; }
  okCh[ch] = 1;
  lastCur[ch] = (b.response_metadata && b.response_metadata.next_cursor) || '';
  for (const m of (b.messages || [])) {
    scanned++;
    const text = allText(m);
    if (!/pushed to Lokalise/i.test(text)) { continue; }
    if (/cleanup mode/i.test(text)) { continue; }
    if (!(m.reactions || []).some(function (r) { return TICKET.test(r.name); })) { continue; }
    const id = ch + ':' + m.ts;
    if (st.done[id] || seen[id]) { continue; }
    seen[id] = 1;
    const project = text.split('\n')[0].split(':')[0].replace(/\*/g, '').trim();
    const tickets = [];
    for (const t of (text.match(/browse\/([A-Z][A-Z0-9]+-\d+)/g) || [])) { const k = t.replace('browse/', ''); if (tickets.indexOf(k) < 0) { tickets.push(k); } }
    out.push({ json: { channel: ch, ts: m.ts, id: id, project_name: project, tickets_in_post: tickets } });
  }
}
const cutoff = Date.now() - 10 * 86400000;
for (const k of Object.keys(st.done)) { if (st.done[k] < cutoff) { delete st.done[k]; } }
// Channels still holding more history after the 10-page cap (2,000 msgs): posts older than that were not checked.
st.last_truncated = Object.keys(lastCur).filter(function (k) { return lastCur[k]; });
st.last_errors = errors; st.last_run = new Date().toISOString(); st.last_scanned = scanned;
if (Object.keys(okCh).length === 0 && errors.length) {
  // Fail loudly: the live watcher swallowed channel_not_found on every run for weeks.
  throw new Error('Slack history failed for every channel: ' + errors.join('; '));
}
return out;

// Skip posts whose thread already has the Claude request. Those count as done.
const st = $getWorkflowStaticData('global');
st.done = st.done || {};
const cands = $('Pick ticketed posts').all();
const res = $input.all(); const out = [];
for (let i = 0; i < res.length; i++) {
  const c = cands[i].json; const b = res[i].json || {};
  if (!b.ok) { continue; }  // replies lookup failed: try again next poll
  const asked = (b.messages || []).some(function (m) { const t = String(m.text || ''); return t.indexOf('<@U0ADGJUQNC8>') >= 0 && t.indexOf('lokalise-keys-jira-trace') >= 0; });
  if (asked) { st.done[c.id] = Date.now(); continue; }
  out.push({ json: c });
}
return out;

// Mark done only after Slack accepted the post, so failures retry on the next poll.
const st = $getWorkflowStaticData('global');
st.done = st.done || {};
const posts = $('Not asked yet').all();
const res = $input.all(); const out = [];
for (let i = 0; i < res.length; i++) {
  const p = posts[i].json; const b = res[i].json || {};
  if (b.ok) { st.done[p.id] = Date.now(); }
  out.push({ json: { id: p.id, channel: p.channel, ts: p.ts, posted: !!b.ok, reply_ts: b.ts || null, error: b.ok ? null : (b.error || 'post failed') } });
}
return out;
